-- Usage videos, ad and video content, hovering promotions, and place delivery fees.
-- Applied once. Do not edit this file after it has been recorded in schema_migrations.

ALTER TABLE products
  ADD COLUMN usage_video_url VARCHAR(500) NULL AFTER description,
  ADD COLUMN handling ENUM('normal', 'delicate', 'perishable') NOT NULL DEFAULT 'normal' AFTER usage_video_url;

ALTER TABLE site_content
  ADD COLUMN kind ENUM('announcement', 'ad', 'video') NOT NULL DEFAULT 'announcement' AFTER entry_type,
  ADD COLUMN link_url VARCHAR(500) NULL AFTER image_url;

ALTER TABLE promotions
  ADD COLUMN hover_in_empty_space TINYINT(1) NOT NULL DEFAULT 1 AFTER is_active;

CREATE TABLE IF NOT EXISTS delivery_places (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  name VARCHAR(160) NOT NULL,
  normal_fee DECIMAL(12,2) NOT NULL,
  delicate_fee DECIMAL(12,2) NOT NULL,
  perishable_fee DECIMAL(12,2) NOT NULL,
  is_active TINYINT(1) NOT NULL DEFAULT 1,
  sort_order INT NOT NULL DEFAULT 0,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_delivery_places_name (name),
  CONSTRAINT chk_delivery_places_normal CHECK (normal_fee >= 0),
  CONSTRAINT chk_delivery_places_delicate CHECK (delicate_fee >= 0),
  CONSTRAINT chk_delivery_places_perishable CHECK (perishable_fee >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
